//! Olson time zone name -> POSIX `TZ` string, as the AP's libc wants it.
//!
//! The table (`tz/zones.rs`) is generated by `scripts/gen-tz.sh` from the public IANA
//! tz database: every canonical zone and `backward` link, with the POSIX rule its TZif
//! file ends with. A zone it doesn't know makes the `system.timezone` lines disappear.
//! A picker offers [`names`], the zones `zone.tab` lists and UTC, as the official
//! controller does; the other names still resolve, so an imported site keeps its zone.
//!
//! Where it differs from the official controller's table, on purpose:
//! - It also has Etc/UTC, GMT, Europe/Kyiv and the other Etc/ and legacy names, for
//!   which the official sends no time zone lines.
//! - Europe/London, Europe/Dublin, America/Mexico_City and Asia/Jerusalem get current
//!   tzdata's rule, where the official sends an older one.
//! - Ireland's rule is tzdata's rearguard form (summer time is the positive offset),
//!   not the main form's negative summer time; both give the same local time.

mod zones;

use zones::ZONES;

/// The zones a picker offers, sorted by name: those `zone.tab` lists (each country's)
/// and UTC, not the `backward` links (`Asia/Calcutta`, `US/Pacific`) nor `Etc/GMT+5`
/// and the like. [`posix`] knows them all.
pub fn names() -> impl Iterator<Item = &'static str> {
    ZONES.iter().filter(|(_, _, offered)| *offered).map(|(name, ..)| *name)
}

/// Every zone [`posix`] knows, sorted by name: [`names`] and the other canonical zones
/// and links.
pub fn all_names() -> impl Iterator<Item = &'static str> {
    ZONES.iter().map(|(name, ..)| *name)
}

pub fn posix(olson: &str) -> Option<&'static str> {
    ZONES.binary_search_by_key(&olson, |(name, ..)| name).ok().map(|i| ZONES[i].1)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_table_is_sorted_and_unique() {
        assert!(ZONES.windows(2).all(|w| w[0].0 < w[1].0));
    }

    /// A picker offers each country's zones and UTC; the links beside them and the
    /// Etc/ zones still resolve.
    #[test]
    fn a_picker_offers_the_zones_of_zone_tab() {
        let offered: Vec<&str> = names().collect();
        for name in ["UTC", "Europe/Amsterdam", "Europe/Copenhagen", "Europe/Kyiv", "Asia/Kolkata", "America/Los_Angeles", "Africa/Addis_Ababa"] {
            assert!(offered.contains(&name), "{name}");
        }
        for name in ["Asia/Calcutta", "Europe/Kiev", "US/Pacific", "GB-Eire", "W-SU", "Zulu", "Navajo", "Etc/GMT+5", "Etc/UTC", "GMT", "EST5EDT"] {
            assert!(!offered.contains(&name) && posix(name).is_some(), "{name}");
        }
        assert!(offered.len() > 400 && offered.len() < all_names().count(), "{}", offered.len());
        assert!(all_names().all(|name| posix(name).is_some()));
    }

    #[test]
    fn unknown_zones_have_no_rule() {
        assert_eq!(posix("Mars/Olympus_Mons"), None);
        assert_eq!(posix(""), None);
        assert_eq!(posix("Factory"), None);
    }

    /// The zones of the hand-written table the generated one replaced keep their strings,
    /// but for the three Canadian zones whose provinces keep summer time all year from
    /// 2026-11-01 (tzdata 2026e).
    #[test]
    fn earlier_rules_are_unchanged() {
        const CET: &str = "CET-1CEST,M3.5.0,M10.5.0/3";
        const EET: &str = "EET-2EEST,M3.5.0/3,M10.5.0/4";
        const US: [&str; 4] = ["EST5EDT,M3.2.0,M11.1.0", "CST6CDT,M3.2.0,M11.1.0", "MST7MDT,M3.2.0,M11.1.0", "PST8PDT,M3.2.0,M11.1.0"];
        const AU_EAST: &str = "AEST-10AEDT,M10.1.0,M4.1.0/3";
        let earlier = [
            ("UTC", "UTC0"), ("Etc/UTC", "UTC0"), ("GMT", "GMT0"),
            ("Europe/London", "GMT0BST,M3.5.0/1,M10.5.0"), ("Europe/Dublin", "GMT0IST,M3.5.0/1,M10.5.0"), ("Europe/Lisbon", "WET0WEST,M3.5.0/1,M10.5.0"),
            ("Europe/Amsterdam", CET), ("Europe/Belgrade", CET), ("Europe/Berlin", CET), ("Europe/Bratislava", CET), ("Europe/Brussels", CET),
            ("Europe/Budapest", CET), ("Europe/Copenhagen", CET), ("Europe/Ljubljana", CET), ("Europe/Luxembourg", CET), ("Europe/Madrid", CET),
            ("Europe/Monaco", CET), ("Europe/Oslo", CET), ("Europe/Paris", CET), ("Europe/Prague", CET), ("Europe/Rome", CET), ("Europe/Stockholm", CET),
            ("Europe/Vienna", CET), ("Europe/Warsaw", CET), ("Europe/Zagreb", CET), ("Europe/Zurich", CET),
            ("Europe/Athens", EET), ("Europe/Bucharest", EET), ("Europe/Helsinki", EET), ("Europe/Kiev", EET), ("Europe/Kyiv", EET),
            ("Europe/Riga", EET), ("Europe/Sofia", EET), ("Europe/Tallinn", EET), ("Europe/Vilnius", EET),
            ("Europe/Istanbul", "<+03>-3"), ("Europe/Moscow", "MSK-3"),
            ("America/New_York", US[0]), ("America/Detroit", US[0]), ("America/Toronto", US[0]), ("America/Chicago", US[1]), ("America/Winnipeg", "EST5"),
            ("America/Denver", US[2]), ("America/Edmonton", "CST6"), ("America/Phoenix", "MST7"), ("America/Los_Angeles", US[3]), ("America/Vancouver", "MST7"),
            ("America/Anchorage", "AKST9AKDT,M3.2.0,M11.1.0"), ("America/Halifax", "AST4ADT,M3.2.0,M11.1.0"), ("America/Sao_Paulo", "<-03>3"),
            ("America/Mexico_City", "CST6"), ("Pacific/Honolulu", "HST10"), ("Pacific/Auckland", "NZST-12NZDT,M9.5.0,M4.1.0/3"),
            ("Asia/Tokyo", "JST-9"), ("Asia/Seoul", "KST-9"), ("Asia/Shanghai", "CST-8"), ("Asia/Hong_Kong", "HKT-8"), ("Asia/Singapore", "<+08>-8"),
            ("Asia/Kolkata", "IST-5:30"), ("Asia/Dubai", "<+04>-4"), ("Asia/Jerusalem", "IST-2IDT,M3.4.4/26,M10.5.0"),
            ("Australia/Sydney", AU_EAST), ("Australia/Melbourne", AU_EAST), ("Australia/Brisbane", "AEST-10"),
            ("Australia/Adelaide", "ACST-9:30ACDT,M10.1.0,M4.1.0/3"), ("Australia/Perth", "AWST-8"), ("Africa/Johannesburg", "SAST-2"),
        ];
        for (zone, rule) in earlier {
            assert_eq!(posix(zone), Some(rule), "{zone}");
        }
    }

    #[test]
    fn zones_beyond_the_earlier_table_and_old_names_have_rules() {
        assert_eq!(posix("Asia/Bangkok"), Some("<+07>-7"));
        assert_eq!(posix("America/Argentina/Buenos_Aires"), Some("<-03>3"));
        assert_eq!(posix("Asia/Kathmandu"), Some("<+0545>-5:45"));
        assert_eq!(posix("Asia/Calcutta"), posix("Asia/Kolkata"));
        assert_eq!(posix("US/Eastern"), posix("America/New_York"));
        assert_eq!(posix("Eire"), posix("Europe/Dublin"));
    }
}
